"""Tasks: generated by a model from the layer, then every key is checked without a model.

A task survives only if:
  * it cites claims of its own node, all with status "ok" (disputed facts never become answer keys);
  * its structure is valid for its type;
  * the correct answer is supported by the cited claims (word overlap / verbatim gap word / recomputed number);
  * agent A's course-text check passes (numbers come from the node's source units, no term before its node).
Rejected tasks are written to the report with the reason, never silently fixed.
"""
import ast
import json
import operator
import random
import re
from pathlib import Path

from kmg import checks as achecks
from kmg.config import ROOT, domain_pack
from kmg.structure import pack_prereq_terms

from . import llm

TYPES = ("single", "multi", "order", "gap", "calc")
PROMPT = Path(__file__).resolve().parent / "prompts" / "tasks.md"
STOP = set("и в во на не но а с со к ко по о об от до из за для при что как это то же ли или у его ее её их "
           "так также только более менее чем который которая которые которых".split())


def _norm(s):
    return re.sub(r"\s+", " ", (s or "").lower().replace("ё", "е")).strip()


def _stems(s):
    return {w[:5] for w in re.findall(r"[a-zа-яё0-9]+", _norm(s)) if w not in STOP and len(w) > 2}


def _overlap(a, b):
    sa = _stems(a)
    if not sa:
        return 0.0
    return len(sa & _stems(b)) / len(sa)


# ---------- safe arithmetic for calc tasks ----------
_OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv,
        ast.Pow: operator.pow, ast.USub: operator.neg, ast.UAdd: operator.pos}
_FUNCS = {"ln": __import__("math").log, "log": __import__("math").log, "log10": __import__("math").log10,
          "sqrt": __import__("math").sqrt, "exp": __import__("math").exp, "pi": __import__("math").pi}


def safe_eval(expr, vars_):
    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id in vars_:
                return float(vars_[n.id])
            if n.id in _FUNCS and not callable(_FUNCS[n.id]):
                return _FUNCS[n.id]
            raise ValueError("unknown name %s" % n.id)
        if isinstance(n, ast.BinOp) and type(n.op) in _OPS:
            return _OPS[type(n.op)](ev(n.left), ev(n.right))
        if isinstance(n, ast.UnaryOp) and type(n.op) in _OPS:
            return _OPS[type(n.op)](ev(n.operand))
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and callable(_FUNCS.get(n.func.id)) and len(n.args) == 1:
            return _FUNCS[n.func.id](ev(n.args[0]))
        raise ValueError("unsupported expression")
    return ev(ast.parse(expr, mode="eval"))


# ---------- generation ----------
def _node_payload(n, later_terms):
    ok = [c for c in n["claims"] if c["status"] == "ok"]
    return {
        "node_id": n["id"], "title": n["title_novice"],
        "claims": [{"id": c["id"], "text": c["text"], "page": c["page"], "quote": c["quote"]} for c in ok],
        "terms": [{"term": t["term"], "definition": (t.get("definition") or {}).get("text")} for t in n.get("terms_defined", [])],
        "procedure": [p["text"] for p in n.get("procedure", [])],
        "numbers_conditions": [p["text"] for p in n.get("numbers_conditions", [])],
        "worked_examples": [{"label": w.get("label"), "condition": (w.get("condition") or {}).get("text"),
                             "steps": [s.get("text") for s in w.get("steps", [])],
                             "result": (w.get("result") or {}).get("text")} for w in n.get("worked_examples", [])],
        "formulas": [{"latex": f["latex"], "variables": f.get("variables", [])} for f in n.get("formulas", [])],
        "forbidden_terms": sorted(later_terms),
    }


def generate(layer, log_path, min_total=15):
    nodes = sorted(layer["nodes"], key=lambda n: n["order"])
    defined_at = {}
    for n in nodes:
        for t in n.get("terms_defined", []):
            defined_at.setdefault(t["term"], n["order"])
    payload = []
    for n in nodes:
        later = {t for t, k in defined_at.items() if k > n["order"]}
        p = _node_payload(n, later)
        if p["claims"]:
            payload.append(p)
    system = [{"type": "text", "text": PROMPT.read_text(encoding="utf-8").replace("{min_total}", str(min_total))}]
    user = "Шаги курса (JSON):\n" + json.dumps(payload, ensure_ascii=False, indent=1)
    r = llm.call("tasks", system, user, log_path=log_path, tag="tasks:%s" % layer["chapter"]["id"])
    data = llm.parse_json(r["text"])
    return data.get("tasks", []), r


# ---------- validation ----------
def _node_text(n):
    parts = [c["text"] for c in n["claims"] if c["status"] == "ok"] + [c["quote"] for c in n["claims"] if c["status"] == "ok"]
    for k in ("summary", "procedure", "numbers_conditions"):
        parts += [p["text"] for p in n.get(k, [])]
    parts += [(t.get("definition") or {}).get("text", "") + " " + t["term"] for t in n.get("terms_defined", [])]
    return "\n".join(parts)


def _correct_texts(t):
    ty = t["type"]
    if ty == "single":
        return [t["options"][t["answer"]]]
    if ty == "multi":
        return [t["options"][i] for i in t["answer"]]
    if ty == "order":
        return list(t["items"])
    if ty == "gap":
        return [t["prompt"].replace("___", str(t["answer"]))]
    if ty == "calc":
        return [str(t["answer"])]
    return []


def validate(layer, raw_tasks, pack_terms):
    nodes = {n["id"]: n for n in layer["nodes"]}
    kept, rejected = [], []
    for i, t in enumerate(raw_tasks):
        why = None
        n = nodes.get(t.get("node_id"))
        ty = t.get("type")
        if not n:
            why = "нет такого узла"
        elif ty not in TYPES:
            why = "неизвестный тип %r" % ty
        else:
            claims = {c["id"]: c for c in n["claims"]}
            cids = t.get("claim_ids") or []
            if not cids or any(c not in claims for c in cids):
                why = "claim_ids пусты или не из этого узла"
            elif any(claims[c]["status"] != "ok" for c in cids):
                why = "ключ опирается на непроверенное утверждение"
        if not why:
            try:
                if ty in ("single", "multi"):
                    opts = t["options"]
                    if not (3 <= len(opts) <= 5) or len(set(map(_norm, opts))) != len(opts):
                        why = "варианты: нужно 3–5 разных"
                    elif ty == "single" and not (isinstance(t["answer"], int) and 0 <= t["answer"] < len(opts)):
                        why = "answer вне диапазона"
                    elif ty == "multi" and not (isinstance(t["answer"], list) and 2 <= len(set(t["answer"])) < len(opts)
                                                and all(isinstance(a, int) and 0 <= a < len(opts) for a in t["answer"])):
                        why = "multi: нужно ≥2 верных и не все"
                elif ty == "order":
                    if not (3 <= len(t.get("items", [])) <= 6):
                        why = "order: нужно 3–6 пунктов"
                elif ty == "gap":
                    if t.get("prompt", "").count("___") != 1 or not str(t.get("answer", "")).strip():
                        why = "gap: нужен ровно один ___ и ответ"
                elif ty == "calc":
                    c = t.get("calc") or {}
                    val = safe_eval(c["expr"], c.get("vars", {}))
                    tol = float(c.get("tolerance", 0.01))
                    ans = float(t["answer"])
                    if abs(val - ans) > max(tol, abs(val) * 0.005):
                        why = "calc: пересчёт %.4g ≠ ключ %.4g" % (val, ans)
            except (KeyError, TypeError, ValueError, ZeroDivisionError, SyntaxError) as e:
                why = "структура: %s" % e
        if not why:
            support = "\n".join(claims[c]["text"] + " " + claims[c]["quote"] for c in t["claim_ids"])
            ntext = _node_text(n)
            if ty == "gap":
                if _norm(str(t["answer"])) not in _norm(ntext):
                    why = "ответ пропуска не встречается в тексте шага"
            elif ty in ("single", "multi"):
                for ct in _correct_texts(t):
                    if _overlap(ct, support) < 0.5:
                        why = "верный вариант не подтверждается утверждениями: «%s»" % ct[:60]
                        break
            elif ty == "order":
                for it in t["items"]:
                    if _overlap(it, ntext) < 0.5:
                        why = "пункт порядка не из шага: «%s»" % it[:60]
                        break
        if not why:
            item = {"node_id": n["id"], "where": "task%d" % i,
                    "text": " ".join([t.get("prompt", "")] + _correct_texts(t) + [t.get("explanation", "")])}
            res = achecks.check_course_items(layer, [item], pack_terms)
            if not res["passed"]:
                why = "проверка A: " + "; ".join(x["message"] for x in res["issues"] if x["level"] == "error")[:200]
        if why:
            rejected.append({"index": i, "node_id": t.get("node_id"), "type": ty, "prompt": t.get("prompt"), "why": why})
            continue
        tid = "%s.t%02d" % (n["id"], sum(1 for k in kept if k["node_id"] == n["id"]) + 1)
        out = {"id": tid, "node_id": n["id"], "claim_ids": t["claim_ids"], "type": ty, "prompt": t["prompt"],
               "explanation": t.get("explanation", ""), "by": "model", "checked": "auto"}
        if ty in ("single", "multi"):
            out["options"], out["answer"] = t["options"], t["answer"]
        elif ty == "order":
            rnd = random.Random(tid)
            idx = list(range(len(t["items"])))
            while idx == sorted(idx):
                rnd.shuffle(idx)
            out["items"] = t["items"]
            out["shuffled"] = idx
        elif ty == "gap":
            out["answer"] = str(t["answer"])
            out["accept"] = [str(a) for a in t.get("accept", [])]
        elif ty == "calc":
            out["answer"] = float(t["answer"])
            out["calc"] = t["calc"]
        kept.append(out)
    return kept, rejected


def build_tasks(layer, out_dir, log_path, min_total=15):
    pack_terms = pack_prereq_terms(domain_pack(layer["chapter"]["domain_pack"]))
    raw, r = generate(layer, log_path, min_total=min_total)
    kept, rejected = validate(layer, raw, pack_terms)
    types = sorted({t["type"] for t in kept})
    report = {"schema": "kmg-tasks/0.1.0", "chapter": layer["chapter"]["id"], "generated": len(raw),
              "kept": len(kept), "rejected": rejected, "types": types,
              "meets_tz": len(kept) >= min_total and len(types) >= 4,
              "cost_usd": r["cost_usd"], "cost_usd_original": r["cost_usd_original"], "cached": r["cached"],
              "model": r["model"]}
    Path(out_dir).mkdir(parents=True, exist_ok=True)
    (Path(out_dir) / "tasks.json").write_text(json.dumps({"schema": "kmg-tasks/0.1.0", "tasks": kept}, ensure_ascii=False, indent=1), encoding="utf-8")
    return kept, report
